{"tool":"write","path":"reports/export.py","content":""""Reports CSV exporter."""

_SPECIALS = (",", '"', "\r", "\n")


def _format_field(value):
    if value is None:
        text = ""
    else:
        text = str(value)
    if any(ch in text for ch in _SPECIALS):
        text = '"' + text.replace('"', '""') + '"'
    return text


def _format_record(values):
    return ",".join(_format_field(v) for v in values)


def export_csv(rows, columns):
    """Export mappings in column order as RFC 4180 CSV, including the header.

    rows: iterable of mappings.
    columns: ordered iterable of unique string column names.
    Returns a str: header record, then one record per row, CRLF-terminated.
    """
    cols = list(columns)
    for name in cols:
        if not isinstance(name, str):
            raise ValueError("column names must be strings: %r" % (name,))
    if len(set(cols)) != len(cols):
        raise ValueError("column names must be unique")

    lines = [_format_record(cols)]
    for row in rows:
        lines.append(_format_record(row.get(name) for name in cols))
    return "".join(line + "\r\n" for line in lines)
